    "sha256": "a1519897f568941aacc31a1c5c594ce3d111b575b8597a7a3acea452441c163e"
  },
  "image_inputs": [
    {
      "role": "identity + south first frame",
      "local_path": "assets/robot-base.png",
      "sha256": "d997cadefc6b94c1c14f4ec17159deaf5ceb7ea9543b2522390ea1a577470aa7",
      "request_field": "first_frame_url",
      "handle": "upload:57ceb659-b047-49e5-9250-58343f194c5f",
      "handle_kind": "PixelLab upload ref (3-day temporary transport), obtained by POSTing the exact file bytes to get_upload_url at 2026-11-12T08:09:03Z; reply: width 32, height 32, n_frames 1",
      "raw_upload_reply": "work/native-production/upload-response.raw.json"
    }
  ],
  "delivered_scope": {
    "preserved": [
      {
        "path": "assets/robot/south.png",
        "sha256": "d997cadefc6b94c1c14f4ec17159deaf5ceb7ea9543b2522390ea1a577470aa7",
        "role": "exact copy of assets/robot-base.png (already written, verified identical)"
      }
    ],
    "generated": [
      "assets/robot/east.png",
      "assets/robot/north.png",
      "assets/robot/west.png"
    ],
    "retained_not_delivered": "south-east, north-east, north-west, south-west views returned by n_directions=8 (kept under work/native-production, not delivered)",
    "family_delivery": "work/native-production/packet-01/family-plan-draft.json",
    "south_baseline": "work/native-production/packet-01/south-baseline-plan.json"
  },
  "choices": [
    {
      "id": "operation",
      "where": "request.tool / provider-arguments.json",
      "choice": "create_object_pro_flash with the exact source as first_frame_url and n_directions=8",
      "reason": "Cheapest discovered route (rotations only, quoted 1 generation) that takes the actual pixels as the south frame without a humanoid skeleton assumption; the robot is a limbless box, which create_character v3 documents as a body it 'tends to add limbs' to. Fallbacks ranked in discovery-01.json.",
      "authority": "specialist choice"
    },
    {
      "id": "view_side",
      "where": "provider-arguments.json view; contract.view 'side'",
      "choice": "view = 'side' (eye level)",
      "reason": "The source is drawn strictly frontal with no visible top face; an eye-level camera keeps the preserved south consistent with the generated views. 'low top-down' would invent a top surface the south frame does not have. Open to caller correction if the game camera is known to be top-down.",
      "authority": "specialist choice (proposal)"
    },
    {
      "id": "n_directions_8",
      "where": "provider-arguments.json n_directions",
      "choice": "8 (tool offers only 1 or 8)",
      "reason": "East/north/west are only available through the 8-view rotation; the four diagonals are retained but not delivered.",
      "authority": "tool constraint"
    },
    {
      "id": "description_text",
      "where": "provider-arguments.json description",
      "choice": "Literal description of the observed source pixels; no new features",
      "reason": "The tool documents description as guidance beside the first frame; it names only what the image already shows.",
      "authority": "specialist choice"
    },
    {
      "id": "seed_0",
      "where": "provider-arguments.json seed",
      "choice": "seed 0 recorded explicitly",
      "reason": "Reproducibility of the attempt record; a revision would use a different seed.",
      "authority": "specialist choice"
    },
    {
      "id": "alpha_binary",
      "where": "contract.alpha, criterion alpha_binary",
      "choice": "binary alpha",
      "reason": "Matches the source (0 fractional pixels) and nearest sampling; proposal, not an owner rule.",
      "authority": "specialist choice (proposal)"
    },
    {
      "id": "palette_exact_set",
      "where": "criterion palette_preserved",
      "choice": "'preserve palette' read as: only the three source colours",
      "reason": "Most literal reading of the brief; a turned face could arguably use one added shade while still 'preserving the palette' in spirit. The caller may relax this to 'no colours outside the source palette family' if it reads the brief differently.",
      "authority": "specialist interpretation of an owner requirement"
    },
    {
      "id": "tolerances",
      "where": "criteria proportions_volume, ground_line_measure",
      "choice": "±1 px height / centre tolerance; bottom row 27",
      "reason": "Measurement proxies for the owner's qualitative proportion/alignment requirements; the numbers are the specialist's.",
      "authority": "specialist choice (proposal)"
    },
    {
      "id": "sample_then_family",
      "where": "state plan (review-context.md)",
      "choice": "One sample-phase generation task (plar_prepare) proves the method; accepted bytes are then reused as production-stage members under a family delivery with the preserved south as baseline; no second paid call unless a revision is needed",
      "reason": "PX2 family members must be production outputs sharing a sample baseline; the representative sample supplies the adoption proof.",
      "authority": "specialist choice (process)"
    },
    {
      "id": "deferred_family_checks",
      "where": "family-plan-draft.json",
      "choice": "Continuity, direction mapping and renderer (engine) checks are family-level, reviewed after all four files exist",
      "reason": "They cannot pass on a single direction; deferral keeps the obligation scheduled rather than dropped.",
      "authority": "specialist choice (process)"
    }
  ],
  "budget": {
    "assignment_limit_generations": 20,
    "expected_this_call": 1,
    "provisional": true,
    "spent_so_far": 0
  }
}

